<?php use Tecnodata\Lms\Core\Csrf; ?><div class="page-heading"><div><span class="eyebrow">MIGRAÇÃO</span><h1>Importar Moodle</h1><p>Analise primeiro. A plataforma bloqueia componentes sem conversor.</p></div></div><?php if($analysis):$a=$analysis['data'];?><section class="panel mb-4"><div class="d-flex justify-content-between align-items-start gap-3"><div><h2><?=e($a['course']['fullname'])?></h2><p class="text-secondary mb-2"><?=e($a['course']['shortname'])?> · <?=$a['sections_count']?> seções · <?=count($a['activities'])?> atividades · <?=$a['questions_count']?> questões detectadas</p><?php foreach($a['activity_counts'] as $t=>$n):?><span class="type-pill"><?=e($t)?> <?=$n?></span><?php endforeach;?></div><span class="compat <?=$a['compatible']?'ok':'warn'?>"><?=$a['compatible']?'Compatível':'Revisão necessária'?></span></div><?php if(!$a['compatible']):?><div class="alert alert-warning mt-3">Sem conversor: <?=e(implode(', ',$a['unknown_types']))?>. A importação definitiva está bloqueada.</div><?php else:?><form method="post" action="/admin/imports/<?=$analysis['id']?>/execute" class="mt-3"><?=Csrf::field()?><button class="btn btn-brand">Importar curso</button></form><?php endif;?></section><?php endif;?><section class="panel mb-4"><h2>Novo backup .mbz</h2><form method="post" enctype="multipart/form-data" action="/admin/imports"><?=Csrf::field()?><div class="input-group"><input class="form-control" type="file" name="backup" accept=".mbz" required><button class="btn btn-brand">Analisar</button></div></form></section><section class="panel"><h2>Histórico</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Arquivo</th><th>Status</th><th>Data</th></tr></thead><tbody><?php foreach($imports as $i):?><tr><td><?=e($i['original_name'])?></td><td><span class="status-badge"><?=e($i['status'])?></span></td><td><?=e($i['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></section>